from itertools import combinations
from functools import lru_cache

def bits(x):
    while x:
        y=x & -x
        yield y
        x-=y

def maximal(fs):
    fs=set(fs)
    return tuple(sorted(f for f in fs if not any(f!=g and f & g == f for g in fs)))

@lru_cache(None)
def kd(fs,k):
    if len(fs)==1:return True
    ranks={f.bit_count() for f in fs}
    if len(ranks)!=1:return False
    q=next(iter(ranks))
    faces=set()
    for f in fs:
        vs=list(bits(f))
        for s in range(1,min(k+1,q)+1):
            for t in combinations(vs,s):faces.add(sum(t))
    for s in sorted(faces,key=lambda x:(x.bit_count(),x)):
        de=[];li=[]
        for f in fs:
            if f&s==s:
                li.append(f^s)
                de.extend(f^v for v in bits(s))
            else:de.append(f)
        de=maximal(de)
        if any(f.bit_count()!=q for f in de):continue
        if kd(de,k) and kd(maximal(li),k):return True
    return False

@lru_cache(None)
def sh(fs):
    if len(fs)==1:return True
    q=fs[0].bit_count()
    for f in fs:
        rest=tuple(g for g in fs if g!=f)
        inter=maximal(f&g for g in rest)
        if all(g.bit_count()==q-1 for g in inter) and sh(rest):return True
    return False

for n,q in [(5,3),(6,4)]:
    facets=[sum(1<<v for v in c) for c in combinations(range(n),q)]
    count=0
    for mask in range(1,1<<len(facets)):
        fs=tuple(sorted(f for i,f in enumerate(facets) if mask>>i&1))
        a=sh(fs);b=kd(fs,q-1)
        assert a==b,(fs,a,b)
        count+=1
    print(f'n={n}, rank={q}: checked shellability iff (rank-1)-decomposability for {count} nonempty pure complexes',flush=True)

